// @domain: awareness
//! Settings (#4478 AC6): an environment variable wins, then `<product>.toml` beside the
//! binary, then the model's default. Secrets are named here, never written: the setting
//! holds the NAME of the environment variable that carries the secret.
//! Generated by athena-gen from its template — DO NOT EDIT; change the generator.

use crate::model::{PRODUCT, SETTINGS};
use std::collections::BTreeMap;

pub struct Settings {
    pub bind: String,
    pub store_kind: String,
    pub store_endpoint: String,
    pub store_path: String,
    pub store_user_var: String,
    pub store_password_var: String,
    /// #4716 — `store.kind = door`: the door every write goes through, and the
    /// command that prints this service's own current token (never the store's password).
    pub store_door: String,
    pub store_token_command: String,
    pub identity_issuer: String,
    /// #4519 — the graphs the shared verifier reads this product's people from
    pub identity_graph_prefix: String,
    pub events_command: String,
    /// #4524 — may anyone read without signing in? Default no: every read names its caller
    /// and returns only that caller's rows and grants. A product that serves public data
    /// (pulse) declares `reads.public = true` in its model, so nothing changes by accident.
    pub reads_public: bool,
}

impl Settings {
    pub fn store_auth(&self) -> Option<(String, String)> {
        let u = std::env::var(&self.store_user_var).ok()?;
        let p = std::env::var(&self.store_password_var).ok()?;
        Some((u, p))
    }
}

fn file_values(path: &str) -> BTreeMap<String, String> {
    // `key = "value"` lines; anything else is ignored. Kept tiny on purpose.
    let mut out = BTreeMap::new();
    if let Ok(text) = std::fs::read_to_string(path) {
        for line in text.lines() {
            if let Some((k, v)) = line.split_once('=') {
                let k = k.trim();
                if !k.starts_with('#') && !k.is_empty() {
                    out.insert(k.to_string(), v.trim().trim_matches('"').to_string());
                }
            }
        }
    }
    out
}

/// The value of one declared setting: env `<PRODUCT>_<KEY>` (dots become underscores),
/// then the file, then the model default. A key the model does not declare is refused.
pub fn value(key: &str, file: &BTreeMap<String, String>) -> String {
    let Some((_, default)) = SETTINGS.iter().find(|(k, _)| *k == key) else {
        panic!("setting '{key}' is not declared in the model for {PRODUCT}");
    };
    // #4519 — a product named with a hyphen (wine-diary) still gets a settable name: WINE_DIARY_SERVER_BIND
    let env = format!("{}_{}", PRODUCT.to_uppercase().replace('-', "_"), key.to_uppercase().replace(['.', '-'], "_"));
    std::env::var(&env).ok().or_else(|| file.get(key).cloned()).unwrap_or_else(|| default.to_string())
}

/// A setting the model may leave undeclared: its value, or `default` when no row declares it.
pub fn optional(key: &str, file: &BTreeMap<String, String>, default: &str) -> String {
    if SETTINGS.iter().any(|(k, _)| *k == key) { value(key, file) } else { default.to_string() }
}

pub fn load() -> Settings {
    let path = std::env::var(format!("{}_SETTINGS", PRODUCT.to_uppercase().replace('-', "_"))).unwrap_or_else(|_| format!("{PRODUCT}.toml"));
    let file = file_values(&path);
    Settings {
        bind: value("server.bind", &file),
        store_kind: value("store.kind", &file),
        store_endpoint: value("store.endpoint", &file),
        store_path: value("store.path", &file),
        store_user_var: value("store.user_var", &file),
        store_password_var: value("store.password_var", &file),
        store_door: optional("store.door", &file, "http://localhost:3360"),
        // #4716 — the product's own identity, minted by the shared cached script
        store_token_command: optional("store.token_command", &file, &format!(
            "{}/CascadeProjects/chorus/platform/scripts/chorus-identity-token {}", std::env::var("HOME").unwrap_or_default(), PRODUCT)),
        identity_issuer: value("identity.issuer", &file),
        identity_graph_prefix: value("identity.graph_prefix", &file),
        events_command: value("events.command", &file),
        reads_public: optional("reads.public", &file, "false") == "true",
    }
}
